WITH joined AS (SELECT s.id, s.email, s.dept_id, s.manager_id, s.salary, s.hire_date, s.is_remote, s.level, d.budget, d.location FROM employees s LEFT JOIN departments d ON s.dept_id = d.id WHERE d.location = 'Bangkok') SELECT CASE WHEN salary >= 120000 THEN 'PREMIUM' ELSE 'STANDARD' END AS salary_tier, DATE_TRUNC('YEAR', hire_date) AS year_start, CASE WHEN budget >= 3145000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, STDDEV_SAMP(salary) AS salary_stddev, APPROX_PERCENTILE(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, COUNT(DISTINCT level) AS distinct_levels, DENSE_RANK() OVER (PARTITION BY CASE WHEN salary >= 120000 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(DISTINCT level) DESC) AS distinct_levels_dense_rank FROM joined GROUP BY CASE WHEN salary >= 120000 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', hire_date), CASE WHEN budget >= 3145000 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY budget_tier NULLS FIRST;
